import itertools
from collections import defaultdict

def parse(text):
    return [ (t.split('::=')[0], t.split('::=')[1].split('|')) for t in text.split(' ') if t ]

def build_all(text):
    rules=parse(text); NT=[l for l,_ in rules]; NTS=set(NT)
    term=sorted({c for l,rs in rules for r in rs for c in r if c not in NTS and c!='@'})
    nullable=set(); ch=True
    while ch:
        ch=False
        for l,rs in rules:
            for r in rs:
                if r=='@' or all(c in nullable for c in r):
                    if l not in nullable: nullable.add(l); ch=True
    FIRST={n:set() for n in NTS}
    def fs(s):
        if s=='@': return {'@'}
        o=set()
        for c in s:
            if c in NTS:
                o|=FIRST[c]-{'@'}
                if '@' not in FIRST[c]: return o
            else: o.add(c); return o
        o.add('@'); return o
    ch=True
    while ch:
        ch=False
        for l,rs in rules:
            for r in rs:
                a=fs(r)
                if not a<=FIRST[l]: FIRST[l]|=a; ch=True
    start=rules[0][0]
    FOL={n:set() for n in NTS}; FOL[start].add('#'); ch=True
    while ch:
        ch=False
        for l,rs in rules:
            for r in rs:
                if r=='@': continue
                for i,c in enumerate(r):
                    if c not in NTS: continue
                    suf=r[i+1:]
                    if suf=='': a=set(FOL[l])
                    else:
                        f=fs(suf); a=f-{'@'}
                        if '@' in f: a|=FOL[l]
                    if not a<=FOL[c]: FOL[c]|=a; ch=True
    FOLH={n:FOL[n]|{'#'} for n in NTS}
    def tab(F):
        t={}
        for l,rs in rules:
            for r in rs:
                f=fs(r)
                for x in f-{'@'}: t.setdefault((l,x),[]).append(f"{l}::={r}")
                if '@' in f:
                    for x in F[l]: t.setdefault((l,x),[]).append(f"{l}::={r}")
        return t
    return rules,NTS,NT,term,nullable,FIRST,FOL,FOLH,tab(FOL),tab(FOLH),start

def drive(NTS,tbl,start,inp):
    st=['#',start]; s=inp+'#'; i=0; n=0
    while True:
        n+=1
        if n>5000: return 'LOOP'
        top=st[-1]; a=s[i]
        if top=='#': return 'ACCEPT' if a=='#' else 'REJECT'
        if top in NTS:
            c=tbl.get((top,a))
            if not c: return 'REJECT'
            st.pop()
            r=c[0].split('::=')[1]
            if r!='@': st.extend(reversed(r))
        else:
            if top==a: st.pop(); i+=1
            else: return 'REJECT'

# brute-force language membership by BFS derivation with length bound
def in_lang(rules,NTS,start,target,maxlen=9):
    from collections import deque
    seen={start}; q=deque([start])
    while q:
        s=q.popleft()
        if s==target: return True
        # prune
        termcount=sum(1 for c in s if c not in NTS)
        if termcount>len(target): continue
        if len(s)>len(target)+8: continue
        idx=next((i for i,c in enumerate(s) if c in NTS),None)
        if idx is None: continue
        # leftmost terminal prefix must match
        if s[:idx]!=target[:idx]: continue
        for l,rs in rules:
            if l!=s[idx]: continue
            for r in rs:
                nw=s[:idx]+('' if r=='@' else r)+s[idx+1:]
                if nw not in seen and len(nw)<=len(target)+8:
                    seen.add(nw); q.append(nw)
    return False

for path,nm in [('/workspace/Parser/test1.txt','G1'),('/workspace/Parser/test2.txt','G2'),('/workspace/Parser/test3.txt','G3')]:
    rules,NTS,NTord,term,nullable,FIRST,FOL,FOLH,Tstd,Thash,start=build_all(open(path).read())
    added=sorted(set(Thash)-set(Tstd)); removed=sorted(set(Tstd)-set(Thash))
    changed=[k for k in set(Tstd)&set(Thash) if Tstd[k]!=Thash[k]]
    print(f"{nm}: rule-order NT={NTord}  ascii-order NT={sorted(NTS)}  MATCH={NTord==sorted(NTS)}")
    print(f"   cells ADDED by always-#: {[(a,b,Thash[(a,b)]) for a,b in added]}  removed={removed} changed={changed}")
    print(f"   conflicts std={[k for k,v in Tstd.items() if len(v)>1]} alw#={[k for k,v in Thash.items() if len(v)>1]}")
    # exhaustive: all strings over terminals up to length L, compare std vs alw# vs true language
    L=6 if len(term)<=5 else 5
    bad=[]; langmismatch=[]
    tot=0
    for n in range(0,L+1):
        for tup in itertools.product(term,repeat=n):
            s=''.join(tup); tot+=1
            a=drive(NTS,Tstd,start,s); b=drive(NTS,Thash,start,s)
            if a!=b: bad.append((s,a,b))
            if n<=5:
                truth=in_lang(rules,NTS,start,s)
                if (a=='ACCEPT')!=truth: langmismatch.append((s,a,truth))
    print(f"   exhaustive |Sigma|={len(term)} up to len {L}: {tot} strings; std-vs-alw# verdict diffs={bad[:10]} (n={len(bad)})")
    print(f"   table-vs-true-language mismatches (len<=5): {langmismatch[:10]} (n={len(langmismatch)})")
    print()
