from collections import defaultdict
# "naive suffix" FOLLOW reading of parser_follow_core.yaml:
# "use suffix FIRST sets when available, recurse to parent FOLLOW sets at rule ends, and always add #"
# i.e. NO recursion to parent FOLLOW when suffix is non-empty but nullable.
def parse(t): return [(x.split('::=')[0], x.split('::=')[1].split('|')) for x in t.split(' ') if x]
def run(path,nm):
    rules=parse(open(path).read()); NTS={l for l,_ in rules}
    FIRST={n:set() for n in NTS}
    def fs(s):
        if s=='@': return {'@'}
        o=set()
        for c in s:
            if c in NTS:
                o|=FIRST[c]-{'@'}
                if '@' not in FIRST[c]: return o
            else: o.add(c); return o
        o.add('@'); return o
    ch=True
    while ch:
        ch=False
        for l,rs in rules:
            for r in rs:
                a=fs(r)
                if not a<=FIRST[l]: FIRST[l]|=a; ch=True
    start=rules[0][0]
    def naive(X,seen=None,strip=True):
        seen=seen or set()
        if X in seen: return {'#'}
        seen=seen|{X}
        out={'#'}                      # "always add #"
        for l,rs in rules:
            for r in rs:
                if r=='@': continue
                for i,c in enumerate(r):
                    if c!=X: continue
                    suf=r[i+1:]
                    if suf=='': out|=naive(l,seen,strip)
                    else:
                        f=fs(suf)
                        out|= (f-{'@'}) if strip else f
        return out
    for strip in (True,False):
        print(f"  {nm} naive-suffix FOLLOW (strip@={strip}):",
              {n:'{'+','.join(sorted(naive(n)if strip else naive(n,None,False)))+'}' for n,_ in rules})
for p,n in [('/workspace/Parser/test1.txt','G1'),('/workspace/Parser/test2.txt','G2'),('/workspace/Parser/test3.txt','G3')]:
    run(p,n)
